INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('KYC_VERIFICATION', 1, 'REJECT', '{"require": "verified"}', 'Customer KYC verification is mandatory for transfers', true);
INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('ACCOUNT_STATUS', 1, 'REJECT', '{"require": "active"}', 'Transfers cannot involve frozen accounts', true);
INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('INSUFFICIENT_FUNDS', 1, 'REJECT', '{}', 'Transfer quantity must not exceed available quantity', true);
INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('NEW_COUNTERPARTY', 1, 'REQUIRE_EXTRA_CONFIRMATION', '{}', 'First-time transfer to a new counterparty requires secondary confirmation', true);
INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('HIGH_VELOCITY', 1, 'REQUIRE_EXTRA_CONFIRMATION', '{"window_hours": 1, "max_transfers": 3}', 'High transaction velocity exceeds single-hour frequency limit', true);
INSERT INTO risk_rule (code, version, outcome, params, description, active) VALUES ('LARGE_VALUE_THRESHOLD', 1, 'REQUIRE_EXTRA_CONFIRMATION', '{"BTC": 1.5, "ETH": 5.0, "SOL": 25.0, "TCS": 50, "RELIANCE": 50, "INFY": 50, "DEFAULT": 100}', 'Single transfer meets or exceeds risk screening threshold', true);
